CREATE TABLE IF NOT EXISTS "RepairOrders"(id serial PRIMARY KEY,"userId" integer NOT NULL,"actorId" integer NOT NULL,"unitId" integer,"saleId" integer,"clientId" integer,"customerName" varchar(160) NOT NULL,"customerPhone" varchar(50),"deviceName" varchar(160) NOT NULL,serial varchar(100),imei varchar(15),issue text NOT NULL,condition text NOT NULL,accessories varchar(250),status varchar(24) NOT NULL DEFAULT 'RECEIVED',"warrantyUntil" date,"warrantyStatus" varchar(24) NOT NULL,diagnosis text,estimate numeric(20,2),currency varchar(3),"approvalStatus" varchar(20) NOT NULL DEFAULT 'PENDING',"assignedTo" integer,"deliveredAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "RepairEvents"(id serial PRIMARY KEY,"userId" integer NOT NULL,"orderId" integer NOT NULL,"actorId" integer NOT NULL,kind varchar(30) NOT NULL,"fromStatus" varchar(24),"toStatus" varchar(24),note text NOT NULL,details jsonb NOT NULL DEFAULT '{}',"createdAt" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS repair_tenant_id ON "RepairOrders"("userId",id);
CREATE UNIQUE INDEX IF NOT EXISTS repair_one_active_unit ON "RepairOrders"("userId","unitId") WHERE "unitId" IS NOT NULL AND status NOT IN ('DELIVERED','CANCELLED');
CREATE UNIQUE INDEX IF NOT EXISTS repair_one_active_imei ON "RepairOrders"("userId",imei) WHERE imei IS NOT NULL AND status NOT IN ('DELIVERED','CANCELLED');
CREATE INDEX IF NOT EXISTS repair_order_status ON "RepairOrders"("userId",status,"createdAt");
CREATE INDEX IF NOT EXISTS repair_event_history ON "RepairEvents"("userId","orderId",id);
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='repair_status_values') THEN ALTER TABLE "RepairOrders" ADD CONSTRAINT repair_status_values CHECK(status IN ('RECEIVED','DIAGNOSIS','WAITING_APPROVAL','REPAIRING','READY','DELIVERED','CANCELLED') AND "approvalStatus" IN ('PENDING','APPROVED','DECLINED') AND "warrantyStatus" IN ('ACTIVE','EXPIRED','NONE','UNVERIFIED') AND (estimate IS NULL OR estimate>=0) AND (currency IS NULL OR currency IN ('USD','CDF')) AND (("unitId" IS NULL)=("saleId" IS NULL))); END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='repair_event_owner_fk') THEN ALTER TABLE "RepairEvents" ADD CONSTRAINT repair_event_owner_fk FOREIGN KEY("userId","orderId") REFERENCES "RepairOrders"("userId",id) ON DELETE RESTRICT; END IF;
END $$;
CREATE TRIGGER lumo_repair_event_immutable BEFORE UPDATE OR DELETE ON "RepairEvents" FOR EACH ROW EXECUTE FUNCTION lumo_guard_support_message();
CREATE OR REPLACE FUNCTION lumo_guard_repair_order() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Repair history cannot be deleted'; END IF; IF OLD.status IN ('DELIVERED','CANCELLED') THEN RAISE EXCEPTION 'Closed repair is immutable'; END IF; IF (OLD."userId",OLD."unitId",OLD."saleId",OLD."clientId",OLD."warrantyUntil",OLD."warrantyStatus") IS DISTINCT FROM (NEW."userId",NEW."unitId",NEW."saleId",NEW."clientId",NEW."warrantyUntil",NEW."warrantyStatus") THEN RAISE EXCEPTION 'Repair identity immutable'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER lumo_repair_order_guard BEFORE UPDATE OR DELETE ON "RepairOrders" FOR EACH ROW EXECUTE FUNCTION lumo_guard_repair_order();
